// src/media/sender/estimators/gcc/acknowledgedBitrateEstimator.ts
var AcknowledgedBitrateEstimator = class {
  window = [];
  latestDiscardedSendTimeMs = Number.NEGATIVE_INFINITY;
  reset() {
    this.window = [];
    this.latestDiscardedSendTimeMs = Number.NEGATIVE_INFINITY;
  }
  /**
   * pin RobustThroughputEstimator::SetAlr — no-op on the robust path.
   * Kept so GCC can publish ALR without branching on estimator type.
   */
  setAlr(_inAlr) {
  }
  /** pin RobustThroughputEstimator::SetAlrEndedTime — no-op. */
  setAlrEndedTime(_atTimeMs) {
  }
  /**
   * Ingest ACKed packets. Prefer **receive-time order** (libwebrtc
   * `SortedByReceiveTime`); out-of-order samples are insertion-sorted.
   */
  incomingPacketFeedbackVector(packets) {
    for (const packet of packets) {
      if (!Number.isFinite(packet.receiveTimeMs) || !Number.isFinite(packet.sendTimeMs) || packet.sizeBytes <= 0) {
        continue;
      }
      this.window.push({ ...packet });
      for (let i = this.window.length - 1; i > 0; i--) {
        if (this.window[i].receiveTimeMs >= this.window[i - 1].receiveTimeMs) {
          break;
        }
        const tmp = this.window[i];
        this.window[i] = this.window[i - 1];
        this.window[i - 1] = tmp;
      }
      const newest = this.window[this.window.length - 1];
      if (newest.receiveTimeMs - packet.receiveTimeMs > 1e3) {
        this.window = [];
        this.latestDiscardedSendTimeMs = Number.NEGATIVE_INFINITY;
      }
      while (this.firstPacketOutsideWindow()) {
        const front = this.window.shift();
        this.latestDiscardedSendTimeMs = Math.max(
          this.latestDiscardedSendTimeMs,
          front.sendTimeMs
        );
      }
    }
  }
  /** @returns estimated acked bitrate in bps, or 0 if not ready. */
  bitrate() {
    if (this.window.length < kRobustRequiredPackets) return 0;
    let largestGap = 0;
    let secondLargestGap = 0;
    for (let i = 1; i < this.window.length; i++) {
      const gap = this.window[i].receiveTimeMs - this.window[i - 1].receiveTimeMs;
      if (gap > largestGap) {
        secondLargestGap = largestGap;
        largestGap = gap;
      } else if (gap > secondLargestGap) {
        secondLargestGap = gap;
      }
    }
    let firstSend = Number.POSITIVE_INFINITY;
    let lastSend = Number.NEGATIVE_INFINITY;
    let firstRecv = Number.POSITIVE_INFINITY;
    let lastRecv = Number.NEGATIVE_INFINITY;
    let recvSize = 0;
    let sendSize = 0;
    let firstRecvSize = 0;
    let lastSendSize = 0;
    let numSentInWindow = 0;
    for (const p of this.window) {
      const prior = p.priorUnackedBytes ?? 0;
      const sized = p.sizeBytes + prior;
      if (p.receiveTimeMs < firstRecv) {
        firstRecv = p.receiveTimeMs;
        firstRecvSize = sized;
      }
      lastRecv = Math.max(lastRecv, p.receiveTimeMs);
      recvSize += sized;
      if (p.sendTimeMs < this.latestDiscardedSendTimeMs) {
        continue;
      }
      if (p.sendTimeMs > lastSend) {
        lastSend = p.sendTimeMs;
        lastSendSize = sized;
      }
      firstSend = Math.min(firstSend, p.sendTimeMs);
      sendSize += sized;
      numSentInWindow++;
    }
    recvSize = Math.max(0, recvSize - firstRecvSize);
    sendSize = Math.max(0, sendSize - lastSendSize);
    let recvDurationMs = lastRecv - firstRecv - largestGap + secondLargestGap;
    recvDurationMs = Math.max(recvDurationMs, 1);
    if (numSentInWindow < kRobustRequiredPackets) {
      return recvSize * 8 * 1e3 / recvDurationMs;
    }
    let sendDurationMs = lastSend - firstSend;
    sendDurationMs = Math.max(sendDurationMs, 1);
    const recvBps = recvSize * 8 * 1e3 / recvDurationMs;
    const sendBps = sendSize * 8 * 1e3 / sendDurationMs;
    return Math.min(sendBps, recvBps);
  }
  firstPacketOutsideWindow() {
    if (this.window.length === 0) return false;
    if (this.window.length > kRobustMaxWindowPackets) return true;
    const duration = this.window[this.window.length - 1].receiveTimeMs - this.window[0].receiveTimeMs;
    if (duration > kRobustMaxWindowDurationMs) return true;
    if (this.window.length > kRobustWindowPackets && duration > kRobustMinWindowDurationMs) {
      return true;
    }
    return false;
  }
};
var BitrateEstimator = class {
  sum = 0;
  currentWindowMs = 0;
  prevTimeMs = -1;
  bitrateEstimateKbps = -1;
  bitrateEstimateVar = 50;
  initialWindowMs = 500;
  nonInitialWindowMs = 150;
  uncertaintyScale = 10;
  reset() {
    this.sum = 0;
    this.currentWindowMs = 0;
    this.prevTimeMs = -1;
    this.bitrateEstimateKbps = -1;
    this.bitrateEstimateVar = 50;
  }
  update(atTimeMs, bytes) {
    const rateWindowMs = this.bitrateEstimateKbps < 0 ? this.initialWindowMs : this.nonInitialWindowMs;
    let isSmallSample = false;
    const sampleKbps = this.updateWindow(
      atTimeMs,
      bytes,
      rateWindowMs,
      (small) => {
        isSmallSample = small;
      }
    );
    if (sampleKbps < 0) return;
    if (this.bitrateEstimateKbps < 0) {
      this.bitrateEstimateKbps = sampleKbps;
      return;
    }
    void isSmallSample;
    const scale = this.uncertaintyScale;
    const sampleUncertainty = scale * Math.abs(this.bitrateEstimateKbps - sampleKbps) / (this.bitrateEstimateKbps + sampleKbps);
    const sampleVar = sampleUncertainty * sampleUncertainty;
    const predVar = this.bitrateEstimateVar + 5;
    this.bitrateEstimateKbps = (sampleVar * this.bitrateEstimateKbps + predVar * sampleKbps) / (sampleVar + predVar);
    this.bitrateEstimateVar = sampleVar * predVar / (sampleVar + predVar);
  }
  bitrate() {
    if (this.bitrateEstimateKbps < 0) return 0;
    return this.bitrateEstimateKbps * 1e3;
  }
  expectFastRateChange() {
    this.bitrateEstimateVar += 200;
  }
  updateWindow(nowMs, bytes, rateWindowMs, setSmall) {
    if (nowMs < this.prevTimeMs) {
      this.prevTimeMs = -1;
      this.sum = 0;
      this.currentWindowMs = 0;
    }
    if (this.prevTimeMs >= 0) {
      this.currentWindowMs += nowMs - this.prevTimeMs;
      if (nowMs - this.prevTimeMs > rateWindowMs) {
        this.sum = 0;
        this.currentWindowMs %= rateWindowMs;
      }
    }
    this.prevTimeMs = nowMs;
    let bitrateSample = -1;
    if (this.currentWindowMs >= rateWindowMs) {
      setSmall(false);
      bitrateSample = 8 * this.sum / rateWindowMs;
      this.currentWindowMs -= rateWindowMs;
      this.sum = 0;
    }
    this.sum += bytes;
    return bitrateSample;
  }
};

// src/media/sender/estimators/gcc/linkCapacityEstimator.ts
var LinkCapacityEstimator = class {
  estimateKbps;
  /** Normalized variance; constructor default 0.4. Pin Reset does **not** clear this. */
  deviationKbps = 0.4;
  /**
   * pin `LinkCapacityEstimator::Reset` — clear capacity estimate only.
   * Deviation history is retained (used on AIMD throughput bound transitions).
   */
  reset() {
    this.estimateKbps = void 0;
  }
  /**
   * Full estimator re-init (route change / GccBandwidthEstimator.reset).
   * Not the same as pin Reset() during AIMD state transitions.
   */
  resetAll() {
    this.estimateKbps = void 0;
    this.deviationKbps = 0.4;
  }
  hasEstimate() {
    return this.estimateKbps !== void 0;
  }
  /** Estimated capacity in bps. */
  estimateBps() {
    return Math.round((this.estimateKbps ?? 0) * 1e3);
  }
  /** Diagnostics: current deviation_kbps_ (normalized variance). */
  get deviationKbpsValue() {
    return this.deviationKbps;
  }
  /** Upper bound bps (estimate + 3σ), or +∞ if unknown. */
  upperBoundBps() {
    if (this.estimateKbps === void 0) {
      return Number.POSITIVE_INFINITY;
    }
    return Math.round(
      (this.estimateKbps + 3 * this.deviationEstimateKbps()) * 1e3
    );
  }
  /** Lower bound bps (estimate − 3σ), or 0 if unknown. */
  lowerBoundBps() {
    if (this.estimateKbps === void 0) {
      return 0;
    }
    return Math.round(
      Math.max(0, this.estimateKbps - 3 * this.deviationEstimateKbps()) * 1e3
    );
  }
  onOveruseDetected(acknowledgedRateBps) {
    this.update(acknowledgedRateBps, 0.05);
  }
  onProbeRate(probeRateBps) {
    this.update(probeRateBps, 0.5);
  }
  update(capacitySampleBps, alpha) {
    const sampleKbps = capacitySampleBps / 1e3;
    if (this.estimateKbps === void 0) {
      this.estimateKbps = sampleKbps;
    } else {
      this.estimateKbps = (1 - alpha) * this.estimateKbps + alpha * sampleKbps;
    }
    const norm = Math.max(this.estimateKbps, 1);
    const errorKbps = this.estimateKbps - sampleKbps;
    this.deviationKbps = (1 - alpha) * this.deviationKbps + alpha * errorKbps * errorKbps / norm;
    this.deviationKbps = Math.min(2.5, Math.max(0.4, this.deviationKbps));
  }
  deviationEstimateKbps() {
    return Math.sqrt(this.deviationKbps * (this.estimateKbps ?? 0));
  }
};

